const RATIFIED_VECTOR_IDS = ["FMT-KAT-EMPTY", "FMT-KAT-ACTIVE", "FMT-KAT-HOLD", "FMT-KAT-EMPTY-HOLD", "FMT-KAT-UNBOUND-HOLD", "FMT-KAT-EMPTY-UNBOUND-HOLD"];
// The kind-13 plaintexts of the seven vectors of the C-FMT bytes in force (SHA-256
// 9d3c7e75055875acbfebfe8e657821d1d9cca18d868d0e0aa6dfac3a480f8786 at commit 0fc698f, act #583 6797802180),
// copied verbatim. The six C-API-RR vectors above are the older 9ff945e1 bytes and stay as legacy coverage.
const CURRENT_AUTHORITY_HOLD_PLAINTEXTS = [
  ['FMT-KAT-EMPTY', '53545958504c4e310001000d000000'],
  ['FMT-KAT-ACTIVE', '53545958504c4e310001000d000000'],
  ['FMT-KAT-HOLD', ''],
  ['FMT-KAT-EMPTY-HOLD', ''],
  ['FMT-KAT-UNBOUND-HOLD', ''],
  ['FMT-KAT-EMPTY-UNBOUND-HOLD', ''],
  ['FMT-KAT-HISTORICAL-HOLD', ''],
];

// K13-NONE-FORMAT: kind-13 heldOutputDigest/heldOutputReference are `ob32`. The null value is the
// zero-length TLV value (tag || u32be(0)); a present value is exactly 32 bytes; null is legal exactly
// when heldOutputKind is NONE. Kind 13 stays version 2 and every ratified vector stays byte-identical.
describe('K13-NONE-FORMAT: optional held-output fields of MUTATION_HOLD v2', () => {
  const K13 = M2_KIND.MUTATION_HOLD;
  const holdVector = VECTORS.find((v) => v.id === 'FMT-KAT-HOLD');
  const holdEntry = holdVector.records.find((r) => r.kind === 'MUTATION_HOLD');
  const base = () => ({ ...decodePlaintext(K13, hex(holdEntry.plaintextHex)) });
  const noneHold = (scenario, operation, originalApiState, expectedSuccessCode) => ({
    ...base(), scenario, operation, originalApiState, expectedSuccessCode, expectedStateAfter: 2,
    heldOutputKind: 1, heldOutputDigest: null, heldOutputReference: null,
  });
  // Field offsets inside the plaintext frame: header 15 bytes, then tag(1)||len(4)||value per field.
  function fieldAt(plain, tag) {
    let o = 15;
    for (;;) {
      const t = plain[o]; const n = (plain[o + 1] << 24 | plain[o + 2] << 16 | plain[o + 3] << 8 | plain[o + 4]) >>> 0;
      if (t === tag) return { offset: o, length: n, value: plain.slice(o + 5, o + 5 + n) };
      o += 5 + n;
    }
  }
  // Splice one field's value (length field included) and recompute nothing else.
  function withField(plain, tag, value) {
    const f = fieldAt(plain, tag);
    return concat(plain.slice(0, f.offset + 1), be32(value.length), value, plain.slice(f.offset + 5 + f.length));
  }
  const NONE_ROWS = [['CAPI-S006', 2, 3, 1, 3], ['CAPI-S016', 6, 7, 2, 7]];

  test.each(NONE_ROWS)('%s: a NONE hold has the canonical empty TLV values and round-trips null', (_s, scenario, operation, origin, success) => {
    const hold = noneHold(scenario, operation, origin, success);
    const plain = encodePlaintext(K13, hold);
    expect(fieldAt(plain, 14)).toMatchObject({ length: 0 });
    expect(fieldAt(plain, 15)).toMatchObject({ length: 0 });
    expect(asHex(plain.slice(fieldAt(plain, 14).offset, fieldAt(plain, 16).offset))).toBe('0e000000000f00000000');
    expect(plain.length).toBe(hex(holdEntry.plaintextHex).length - 64);
    const decoded = decodePlaintext(K13, plain);
    expect(decoded).toMatchObject({ heldOutputKind: 1, heldOutputDigest: null, heldOutputReference: null, scenario, operation });
    expect(asHex(encodePlaintext(K13, { ...decoded }))).toBe(asHex(plain));
  });

  test.each(NONE_ROWS)('%s: a NONE hold seals and opens under the ratified envelope, AAD and key schedule', async (_s, scenario, operation, origin, success) => {
    const namespaceKey = await vectorKeys(holdVector);
    const recordKey = hex(holdEntry.keyHex);
    const plaintext = encodePlaintext(K13, noneHold(scenario, operation, origin, success));
    const ad = decodeAad(hex(holdEntry.aadHex));
    const aad = await encodeAad({
      recordKey, localContextId: ad.localContextId, productProfileDigest: ad.productProfileDigest, scope: ad.scope,
      secureSessionIdentity: ad.secureSessionIdentity, canonicalBinding: hex(holdVector.canonicalBindingHex),
      writeGeneration: ad.writeGeneration, mutationIdentity: ad.mutationIdentity, plaintextLength: plaintext.length, recordKind: K13,
    });
    const aeadKey = await deriveRecordAeadKey({ namespaceKey, recordKey });
    const envelope = await sealRecord({ aeadKey, recordKind: K13, recordKey, aad, plaintext, nonce: hex(holdEntry.nonceHex) });
    expect(decodeEnvelope(envelope).recordKindVersion).toBe(2);
    const opened = await openRecord({ aeadKey, envelope, expectedRecordKey: recordKey, expectedAad: aad });
    expect(asHex(opened.plaintext)).toBe(asHex(plaintext));
  });

  test('semantic coupling: null exactly when heldOutputKind is NONE, never half-null', () => {
    const none = noneHold(2, 3, 1, 3);
    const output = base();
    const reject = (v) => expect(() => encodePlaintext(K13, v)).toThrow(expect.objectContaining({ code: 'UNSUPPORTED_VALUE' }));
    reject({ ...none, heldOutputDigest: output.heldOutputDigest });
    reject({ ...none, heldOutputReference: output.heldOutputReference });
    reject({ ...none, heldOutputDigest: output.heldOutputDigest, heldOutputReference: output.heldOutputReference });
    reject({ ...output, heldOutputDigest: null });
    reject({ ...output, heldOutputReference: null });
    reject({ ...output, heldOutputDigest: null, heldOutputReference: null });
    expect(() => encodePlaintext(K13, { ...none, heldOutputDigest: undefined })).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
    expect(() => encodePlaintext(K13, { ...none, heldOutputDigest: new Uint8Array(0) })).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
    expect(() => encodePlaintext(K13, { ...output, heldOutputDigest: new Uint8Array(31) })).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
  });

  test.each([[14], [15]])('decode, tag %i: every other optional length rejects as malformed', (tag) => {
    const none = encodePlaintext(K13, noneHold(2, 3, 1, 3));
    const output = hex(holdEntry.plaintextHex);
    for (const n of [1, 16, 31, 33, 64]) {
      const v = new Uint8Array(n).fill(7);
      expect(() => decodePlaintext(K13, withField(none, tag, v))).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
      expect(() => decodePlaintext(K13, withField(output, tag, v))).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
    }
  });

  // The complete presence matrix at canonical widths: (digest, reference) in {absent, present, all-zero}^2,
  // under NONE and under an output kind. Only (absent, absent) for NONE and (present, present) for an output
  // kind decode; every other combination rejects as UNSUPPORTED_VALUE at decode and at encode.
  const FORMS = { absent: () => new Uint8Array(0), present: () => new Uint8Array(32).fill(7), zero: () => new Uint8Array(32) };
  const MATRIX = [];
  for (const kind of ['NONE', 'OUTPUT']) for (const d of Object.keys(FORMS)) for (const r of Object.keys(FORMS)) {
    const ok = kind === 'NONE' ? d === 'absent' && r === 'absent' : d !== 'absent' && r !== 'absent';
    MATRIX.push([kind, d, r, ok]);
  }
  test.each(MATRIX)('presence matrix: %s digest=%s reference=%s legal=%s', (kind, d, r, ok) => {
    const start = kind === 'NONE' ? encodePlaintext(K13, noneHold(2, 3, 1, 3)) : hex(holdEntry.plaintextHex);
    const plain = withField(withField(start, 14, FORMS[d]()), 15, FORMS[r]());
    const asValue = (x) => (x.length === 0 ? null : x);
    const value = { ...(kind === 'NONE' ? noneHold(2, 3, 1, 3) : base()), heldOutputDigest: asValue(FORMS[d]()), heldOutputReference: asValue(FORMS[r]()) };
    if (ok) {
      const decoded = decodePlaintext(K13, plain);
      expect(asHex(encodePlaintext(K13, { ...decoded }))).toBe(asHex(plain));
      expect(asHex(encodePlaintext(K13, value))).toBe(asHex(plain));
    } else {
      expect(() => decodePlaintext(K13, plain)).toThrow(expect.objectContaining({ code: 'UNSUPPORTED_VALUE' }));
      expect(() => encodePlaintext(K13, value)).toThrow(expect.objectContaining({ code: 'UNSUPPORTED_VALUE' }));
    }
  });

  test.each([['heldOutputDigest'], ['heldOutputReference']])('encode, %s: undefined, empty bytes and wrong widths are malformed', (field) => {
    const none = noneHold(2, 3, 1, 3);
    const output = base();
    for (const bad of [undefined, new Uint8Array(0), new Uint8Array(31), new Uint8Array(33)]) {
      expect(() => encodePlaintext(K13, { ...none, [field]: bad })).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
      expect(() => encodePlaintext(K13, { ...output, [field]: bad })).toThrow(expect.objectContaining({ code: 'MALFORMED_INPUT' }));
    }
  });

  test('every ratified C-FMT vector (all six, ids asserted) keeps its kind-13 plaintext and 32-byte values', () => {
    const all = [...VECTORS, ...UNBOUND_VECTORS];
    expect(all.map((v) => v.id).sort()).toEqual([...RATIFIED_VECTOR_IDS].sort());
    for (const v of all) {
      const entry = v.records.find((r) => r.kind === 'MUTATION_HOLD');
      const value = decodePlaintext(K13, hex(entry.plaintextHex));
      expect(asHex(encodePlaintext(K13, { ...value }))).toBe(entry.plaintextHex);
      if (value.presence === 1) {
        expect(value.heldOutputKind).not.toBe(1);
        expect(value.heldOutputDigest).toHaveLength(32);
        expect(value.heldOutputReference).toHaveLength(32);
      }
    }
  });

  test('the seven vectors of the C-FMT in force, FMT-KAT-HISTORICAL-HOLD included, keep their kind-13 plaintext', () => {
    expect(CURRENT_AUTHORITY_HOLD_PLAINTEXTS.map(([id]) => id)).toEqual([...RATIFIED_VECTOR_IDS, 'FMT-KAT-HISTORICAL-HOLD']);
    for (const [, plaintextHex] of CURRENT_AUTHORITY_HOLD_PLAINTEXTS) {
      const value = decodePlaintext(K13, hex(plaintextHex));
      expect(asHex(encodePlaintext(K13, { ...value }))).toBe(plaintextHex);
      if (value.presence === 1) {
        expect(value.heldOutputKind).not.toBe(1);
        expect(value.heldOutputDigest).toHaveLength(32);
        expect(value.heldOutputReference).toHaveLength(32);
      }
    }
    expect(CURRENT_AUTHORITY_HOLD_PLAINTEXTS.filter(([, h]) => decodePlaintext(K13, hex(h)).presence === 1)).toHaveLength(5);
  });
});

